  pokemon_name text,
  form_name text,
  species_family text
)
on conflict(game_key, pokedex_key, entry_number, pokemon_id, form_name) do update set
  pokemon_name = excluded.pokemon_name,
  species_family = excluded.species_family,
  source_commit = excluded.source_commit;

do $$
begin
  if not exists (
    select 1 from public.pokemon_games
    where game_key='legends-za'
      and pokedex_status='verified'
      and encounter_status='pending'
      and pokedex_source_commit='5064f1d72746b3a6a931616dae3fb6445c556d4f'
      and jsonb_array_length(starters)=3
  ) then
    raise exception 'Pokémon Legends: Z-A capability states do not match the reviewed artifact';
  end if;
  if (select count(*) from public.pokemon_game_pokedex_entries where game_key='legends-za')<>364
    or (select count(*) from public.pokemon_game_pokedex_entries where game_key='legends-za' and pokedex_key='lumiose-city')<>232 or (select count(*) from public.pokemon_game_pokedex_entries where game_key='legends-za' and pokedex_key='hyperspace')<>132
    or (select count(distinct pokemon_id) from public.pokemon_game_pokedex_entries where game_key='legends-za')<>364
  then
    raise exception 'Pokémon Legends: Z-A Pokédex counts do not match the reviewed artifact';
  end if;
  if exists(select 1 from public.pokemon_game_locations where game_key='legends-za')
    or exists(select 1 from public.pokemon_game_encounters where game_key='legends-za')
  then
    raise exception 'Pokémon Legends: Z-A encounter data must remain absent until separately reviewed';
  end if;
end $$;

commit;
